// One fetch per enabled company, isolated by try/catch so a bad source can't kill the run.
const cfg = $('Config').first().json;
const out = [];
const s = (v) => (v == null ? '' : String(v));
const strip = (h) => s(h)
  .replace(/<[^>]*>/g, ' ')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
  .replace(/&nbsp;/g, ' ').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ').trim().slice(0, 1500);
const H = (typeof $helpers !== 'undefined' && $helpers && $helpers.httpRequest) ? $helpers : this.helpers;

for (const c of cfg.companies) {
  if (!c.enabled) continue;
  let url;
  if (c.ats_type === 'greenhouse') url = `https://boards-api.greenhouse.io/v1/boards/${c.token}/jobs?content=true`;
  else if (c.ats_type === 'lever') url = `https://api.lever.co/v0/postings/${c.token}?mode=json`;
  else if (c.ats_type === 'ashby') url = `https://api.ashbyhq.com/posting-api/job-board/${c.token}?includeCompensation=true`;
  else continue;

  let body;
  try {
    body = await H.httpRequest({ method: 'GET', url, json: true, timeout: 20000 });
  } catch (e) {
    out.push({ json: { __error: true, company: c.company, reason: ('fetch failed: ' + s(e.statusCode) + ' ' + s(e.message)).trim() } });
    continue;
  }

  try {
    if (c.ats_type === 'greenhouse') {
      for (const j of (body.jobs || [])) {
        out.push({ json: { company: c.company, title: s(j.title), location: s(j.location && j.location.name), remote: 'uncertain', url: s(j.absolute_url), posted_at: s(j.updated_at), comp: '', description: strip(j.content), external_id: 'greenhouse:' + c.company + ':' + j.id } });
      }
    } else if (c.ats_type === 'lever') {
      for (const j of (Array.isArray(body) ? body : [])) {
        const wt = s(j.workplaceType).toLowerCase();
        out.push({ json: { company: c.company, title: s(j.text), location: s(j.categories && j.categories.location), remote: wt === 'remote' ? 'true' : (wt ? 'false' : 'uncertain'), url: s(j.hostedUrl), posted_at: j.createdAt ? new Date(j.createdAt).toISOString() : '', comp: '', description: strip(j.descriptionPlain || j.description), external_id: 'lever:' + c.company + ':' + j.id } });
      }
    } else if (c.ats_type === 'ashby') {
      for (const j of (body.jobs || [])) {
        out.push({ json: { company: c.company, title: s(j.title), location: s(j.location || j.locationName), remote: j.isRemote === true ? 'true' : (j.isRemote === false ? 'false' : 'uncertain'), url: s(j.jobUrl || j.applyUrl), posted_at: s(j.publishedAt), comp: s(j.compensation && j.compensation.compensationTierSummary), description: strip(j.descriptionPlain || j.descriptionHtml), external_id: 'ashby:' + c.company + ':' + j.id } });
      }
    }
  } catch (e) {
    out.push({ json: { __error: true, company: c.company, reason: 'normalize: ' + s(e.message) } });
  }
}
return out;

// Keep if title matches a role keyword AND the location is acceptable:
//   global / remote-anywhere, pan-EU (EMEA/Europe/EU/EEA), or your home country.
// A specific other country/city (incl. single other countries) is dropped. Empty/ambiguous -> kept.
const cfg = $('Config').first().json;
const kw = cfg.roleKeywords.map(x => x.toLowerCase());
const region = cfg.locationRegion.map(x => x.toLowerCase());
const home = cfg.locationHome.map(x => x.toLowerCase());
const deny = cfg.locationDeny.map(x => x.toLowerCase());

const hit = (text, term) => term.length <= 3
  ? new RegExp('(^|[^a-z])' + term + '($|[^a-z])').test(text)
  : text.includes(term);

const locOk = (rawLoc, remote) => {
  const loc = (rawLoc || '').toLowerCase();
  if (region.some(r => hit(loc, r))) return true;
  if (home.some(h => h && loc.includes(h))) return true;
  if (deny.some(d => hit(loc, d))) return false;
  if (loc === '') return true;
  if (remote === 'true' || loc.includes('remote') || loc.includes('home based')) return true;
  return false;
};

const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (j.__error) continue;
  const title = (j.title || '').toLowerCase();
  if (!kw.some(k => title.includes(k))) continue;
  if (locOk(j.location, j.remote)) out.push({ json: j });
}
return out;

// Batch every NEW job into ONE scoring request for the LLM.
const cfg = $('Config').first().json;
const jobs = $input.all().map(i => i.json);
const clip = (v, n) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, n);

const compact = jobs.map(j => ({
  id: j.external_id,
  company: j.company,
  title: j.title,
  location: j.location,
  description: clip(j.description, 700)
}));

const system = cfg.candidateProfile + '\n\n' +
  'You are a job-fit evaluator. For each job, score 0-100 how well it fits the candidate above ' +
  '(skills overlap, domain interest, seniority, and remote/EU eligibility). 100 = ideal, 0 = irrelevant. ' +
  'Return ONLY a JSON array, no prose. Each element: {"id": "<id>", "score": <int 0-100>, "reason": "<max 12 words>"}.';

const body = {
  model: cfg.llmModel,
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: 'Jobs:\n' + JSON.stringify(compact) }
  ],
  temperature: 0.2,
  max_tokens: 6000
};

return [{ json: { bodyJson: JSON.stringify(body), jobCount: jobs.length } }];

// Merge the LLM scores onto the new jobs, sort best-first, build ONE email. No new jobs => no email.
const fresh = $('Keep only new').all().map(i => i.json);
const failures = [...new Set(
  $('Fetch & normalize').all().map(i => i.json).filter(j => j.__error).map(j => j.company)
)];

if (fresh.length === 0) return [];

// parse the LLM's JSON array of {id, score, reason}; tolerate code fences / prose / total failure
const scoreMap = {};
try {
  let content = $input.first().json.choices[0].message.content || '';
  const m = content.match(/\[[\s\S]*\]/);
  if (m) content = m[0];
  for (const e of JSON.parse(content)) {
    if (e && e.id != null) scoreMap[e.id] = { score: Number(e.score), reason: String(e.reason || '') };
  }
} catch (e) { /* scoring unavailable -> jobs still listed, just unscored */ }

for (const j of fresh) {
  const sc = scoreMap[j.external_id];
  j._score = (sc && Number.isFinite(sc.score)) ? sc.score : null;
  j._reason = sc ? sc.reason : '';
}
fresh.sort((a, b) => (b._score == null ? -1 : b._score) - (a._score == null ? -1 : a._score));

const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const pct = (v) => v == null ? '—' : (v + '%');
const rows = fresh.map(j => {
  const loc = j.location ? (' (' + esc(j.location) + ')') : '';
  const comp = j.comp ? (' — ' + esc(j.comp)) : '';
  const why = j._reason ? (' — <i>' + esc(j._reason) + '</i>') : '';
  return '<li><b>' + pct(j._score) + '</b> — <b>' + esc(j.company) + '</b> — ' + esc(j.title) + loc + comp + why + ' — <a href="' + esc(j.url) + '">link</a></li>';
}).join('');

const n = fresh.length;
const top = fresh[0]._score == null ? 'n/a' : (fresh[0]._score + '%');
let html = '<p><b>' + n + ' new ' + (n === 1 ? 'role' : 'roles') + '</b> — scored vs your profile, best first</p><ul>' + rows + '</ul>';
let subject = n + ' new role' + (n === 1 ? '' : 's') + ' — top match ' + top;
if (failures.length) {
  html += '<p style="color:#b00">⚠️ ' + failures.length + ' source(s) failing: ' + failures.map(esc).join(', ') + '</p>';
  subject += ' (⚠️ ' + failures.length + ' failing)';
}
return [{ json: { subject, html, count: n, freshRows: fresh } }];

// Email already sent: now expand the digest's freshRows back into one item per posting to insert.
const rows = ($('Build digest').first().json.freshRows) || [];
return rows.map(r => ({ json: { external_id: r.external_id, company: r.company, title: r.title, location: r.location || '', url: r.url } }));
